 */
private playBurnEffect(scene: Phaser.Scene, cx: number, cy: number): void {
  // ── 1단계: 큼직한 불꽃 파티클 12개 ─────────────────────────────
  const FIRE_COLORS = [0xff2200, 0xff5500, 0xff8800, 0xffbb00, 0xffee00];
  const FIRE_COUNT  = 12;

  for (let i = 0; i < FIRE_COUNT; i++) {
    const gfx   = scene.add.graphics();
    const color = FIRE_COLORS[Math.floor(Math.random() * FIRE_COLORS.length)];
    const r     = Phaser.Math.Between(5, 12);
    gfx.fillStyle(color, 1);
    gfx.fillCircle(0, 0, r);
    gfx.setPosition(
      cx + Phaser.Math.Between(-14, 14),
      cy + Phaser.Math.Between(-14, 14),
    );
    gfx.setDepth(200);

    const angleDeg = Phaser.Math.Between(190, 350); // 위쪽 부채꼴
    const dist     = Phaser.Math.Between(40, 90);
    const rad      = Phaser.Math.DegToRad(angleDeg);
    const dur      = Phaser.Math.Between(450, 800);

    // 1단계: 솟구침
    scene.tweens.add({
      targets:  gfx,
      x:        gfx.x + Math.cos(rad) * dist,
      y:        gfx.y + Math.sin(rad) * dist,
      scaleX:   1.6,
      scaleY:   1.6,
      duration: dur * 0.4,
      ease:     'Quad.easeOut',
      onComplete: () => {
        // 2단계: 사그라듦
        scene.tweens.add({
          targets:    gfx,
          scaleX:     0,
          scaleY:     0,
          alpha:      0,
          y:          gfx.y - Phaser.Math.Between(10, 25),
          duration:   dur * 0.6,
          ease:       'Quad.easeIn',
          onComplete: () => { gfx.destroy(); },
        });
      },
    });
  }

  // ── 2단계: 잔불 ember 8개 (더 늦게 사그라짐) ────────────────────
  const EMBER_COLORS = [0xff4400, 0xff7700, 0xffcc00];
  const EMBER_COUNT  = 8;

  for (let i = 0; i < EMBER_COUNT; i++) {
    const gfx   = scene.add.graphics();
    const color = EMBER_COLORS[Math.floor(Math.random() * EMBER_COLORS.length)];
    const r     = Phaser.Math.Between(2, 5);
    gfx.fillStyle(color, 0.9);
    gfx.fillCircle(0, 0, r);
    gfx.setPosition(
      cx + Phaser.Math.Between(-18, 18),
      cy + Phaser.Math.Between(-18, 18),
    );
    gfx.setDepth(201);

    const angleDeg = Phaser.Math.Between(180, 360);
    const dist     = Phaser.Math.Between(20, 55);
    const rad      = Phaser.Math.DegToRad(angleDeg);
    const delay    = Phaser.Math.Between(0, 200);

    scene.tweens.add({
      targets:  gfx,
      x:        gfx.x + Math.cos(rad) * dist,
      y:        gfx.y + Math.sin(rad) * dist - Phaser.Math.Between(15, 35),
      alpha:    0,
      scaleX:   0,
      scaleY:   0,
      duration: Phaser.Math.Between(700, 1100),
      delay,
      ease:     'Sine.easeOut',
      onComplete: () => { gfx.destroy(); },
    });
  }
}

