        ease:     'Quad.easeOut',
        onComplete: () => {
          scene.tweens.add({
            targets:    gfx,
            y:          gfx.y - rise * 0.62,
            scaleX:     0,
            scaleY:     0,
            alpha:      0,
            duration:   dur * 0.65,
            ease:       'Quad.easeIn',
            onComplete: () => { gfx.destroy(); },
          });
        },
      });
    }

    // ── 2. 잔불 ember 8개 — 글로우 + 코어 2레이어 ──────────────────
    const EMBER_COLS = [0xff5500, 0xff8800, 0xffbb00];
    for (let i = 0; i < 8; i++) {
      const gfx   = scene.add.graphics();
      const s     = Phaser.Math.Between(2, 5);
      const color = EMBER_COLS[Math.floor(Math.random() * EMBER_COLS.length)];

      // 외곽 글로우 (반투명)
      gfx.fillStyle(color, 0.32);
      gfx.fillPoints([
        { x:  0,      y: -s * 1.9 },
        { x:  s * 1.9, y:  0      },
        { x:  0,      y:  s * 1.9 },
        { x: -s * 1.9, y:  0      },
      ], true);

      // 코어 (밝고 선명)
      gfx.fillStyle(0xffee88, 0.95);
      gfx.fillPoints([
        { x:  0,  y: -s },
        { x:  s,  y:  0 },
        { x:  0,  y:  s },
        { x: -s,  y:  0 },
      ], true);

      gfx.setPosition(
        cx + Phaser.Math.Between(-18, 18),
        cy + Phaser.Math.Between(-18, 18),
      );
      gfx.setDepth(201);

      const rad = Phaser.Math.DegToRad(Phaser.Math.Between(185, 355));
      const dist = Phaser.Math.Between(28, 65);

      scene.tweens.add({
        targets:  gfx,
        x:        gfx.x + Math.cos(rad) * dist,
        y:        gfx.y + Math.sin(rad) * dist - Phaser.Math.Between(18, 40),
        rotation: Phaser.Math.DegToRad(Phaser.Math.Between(200, 400)),
        alpha:    0,
        scaleX:   0,
        scaleY:   0,
        duration: Phaser.Math.Between(650, 1050),
        delay:    Phaser.Math.Between(0, 220),
        ease:     'Sine.easeOut',
        onComplete: () => { gfx.destroy(); },
      });
    }

    // ── 3. 연기 4개 — 어두운 반투명 원, 천천히 위로 퍼짐 ───────────
    for (let i = 0; i < 4; i++) {
      const gfx = scene.add.graphics();
      const r   = Phaser.Math.Between(6, 13);
      gfx.fillStyle(0x331100, 0.28);
      gfx.fillCircle(0, 0, r);
      gfx.setPosition(
        cx + Phaser.Math.Between(-12, 12),
        cy + Phaser.Math.Between(-10, 4),
      );
      gfx.setDepth(199);

      scene.tweens.add({
        targets:  gfx,
        y:        gfx.y - Phaser.Math.Between(45, 85),
        x:        gfx.x + Phaser.Math.Between(-14, 14),
        scaleX:   2.4,
        scaleY:   2.4,
        alpha:    0,
        duration: Phaser.Math.Between(850, 1350),
        delay:    Phaser.Math.Between(80, 380),
        ease:     'Sine.easeOut',
        onComplete: () => { gfx.destroy(); },
      });
    }
  }
}

