import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 레거시 (UR)
 * - 기본 효과: 게임 시작 시 6초간 금똥 2개씩 내려오는 피버타임으로 시작
 *             + 똥 스폰마다 20% 확률로 랜덤 2개 불에 타서 소멸
 * - 특수 능력: 500점마다 레거시 모드 10초 발동
 *             — 점수 1.2배 + 충격파 + 화면 테두리 불꽃 글로우
 *             — 불태우기 강화: 40% 확률로 4개 소멸
 */
export class LegacyAbility extends BaseAbility {
  private startFeverActive = false;
  private legacyModeActive = false;
  private accum = 0;
  private lastLegacyScore = 0;
  private legacyBorder?: Phaser.GameObjects.Graphics;
  private legacyPulseTween?: Phaser.Tweens.Tween;

  override onCreate(api: GameSceneAPI): void {
    this.startFeverActive = true;
    api.scene.time.delayedCall(6000, () => {
      this.startFeverActive = false;
    });
  }

  override getTickScore(base: number): number {
    if (!this.legacyModeActive) return base;
    this.accum += base * 0.2;
    const bonus = Math.floor(this.accum);
    this.accum -= bonus;
    return base + bonus;
  }

  /** 시작 피버 중에는 일반 스폰 대신 금똥 2개 생성 */
  override overrideSpawnPoop(api: GameSceneAPI): boolean {
    if (this.startFeverActive) {
      api.spawnGoldPoop();
      api.spawnGoldPoop();
      return true;
    }
    return false;
  }

  /** 일반 스폰 후: 기본 20%(레거시 모드 중 40%) 확률로 불태우기 */
  override onAfterSpawnPoop(api: GameSceneAPI): void {
    const chance = this.legacyModeActive ? 0.4 : 0.2;
    const count  = this.legacyModeActive ? 4   : 2;
    if (Math.random() < chance) {
      this.burnRandomPoops(api, count);
    }
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % 500 === 0 && score > this.lastLegacyScore) {
      this.lastLegacyScore = score;
      this.activateLegacyMode(api);
    }
  }

  // ── 내부 헬퍼 ─────────────────────────────────────────────────────

  private activateLegacyMode(api: GameSceneAPI): void {
    if (this.legacyModeActive) return;
    this.legacyModeActive = true;
    this.accum = 0;

    const scene = api.scene;

    // ── 1. 화면 전체 amber flash (순간) ─────────────────────────────
    const screenFlash = scene.add.graphics();
    screenFlash.fillStyle(0xff8800, 0.30);
    screenFlash.fillRect(0, 0, 400, 600);
    screenFlash.setDepth(160);
    scene.tweens.add({
      targets:  screenFlash,
      alpha:    0,
      duration: 350,
      ease:     'Quad.easeOut',
      onComplete: () => { screenFlash.destroy(); },
    });

    // ── 2. 충격파 링 3개 (화면 중앙에서 바깥으로 확산) ──────────────
    for (let i = 0; i < 3; i++) {
      const ring = scene.add.graphics();
      ring.lineStyle(4 - i, 0xffcc00, 0.9 - i * 0.15);
      ring.strokeCircle(200, 300, 18);
      ring.setDepth(155);

      scene.tweens.add({
        targets:  ring,
        scaleX:   16,
        scaleY:   11,
        alpha:    0,
        duration: 650,
        delay:    i * 130,
        ease:     'Quad.easeOut',
        onComplete: () => { ring.destroy(); },
      });
    }

    // ── 3. 화면 테두리 불꽃 글로우 (지속, 이중 stroke) ──────────────
    this.legacyBorder = scene.add.graphics();
    // 외곽 두꺼운 오렌지 테두리
    this.legacyBorder.lineStyle(6, 0xff6600, 0.75);
    this.legacyBorder.strokeRect(1, 1, 398, 598);
    // 안쪽 얇은 노란 테두리
    this.legacyBorder.lineStyle(2, 0xffee44, 0.55);
    this.legacyBorder.strokeRect(7, 7, 386, 586);
    this.legacyBorder.setDepth(150);

    // alpha 0.5 ↔ 1.0 펄스 (자연스러운 불꽃 흔들림)
    this.legacyPulseTween = scene.tweens.add({
      targets:  this.legacyBorder,
      alpha:    0.5,
      duration: 550,
      yoyo:     true,
      repeat:   -1,
      ease:     'Sine.easeInOut',
    });

    // 10초 후 종료
    scene.time.delayedCall(10000, () => {
      this.legacyModeActive = false;
      this.legacyPulseTween?.stop();
      this.legacyPulseTween = undefined;
      scene.tweens.add({
        targets:    this.legacyBorder,
        alpha:      0,
        duration:   400,
        ease:       'Quad.easeOut',
        onComplete: () => {
          this.legacyBorder?.destroy();
          this.legacyBorder = undefined;
        },
      });
    });
  }

  /**
   * 화면 위에 있는 일반 똥 중 최대 count개를 골라 불태움.
   * 아직 화면에 진입하지 않은 똥(y < -10)은 제외해 불꽃이 보이도록.
   */
  private burnRandomPoops(api: GameSceneAPI, count: number): void {
    const visible = api.poops.getChildren().filter(
      c => c.active && (c as Phaser.Physics.Arcade.Sprite).y > -10
    ) as Phaser.Physics.Arcade.Sprite[];

    if (visible.length === 0) return;

    // Fisher-Yates 셔플 후 앞 count개 선택 (배열 원본 변경 없이 복사본 사용)
    const pool = visible.slice();
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    const targets = pool.slice(0, Math.min(count, pool.length));

    for (const poop of targets) {
      if (!poop.active) continue;
      this.playBurnEffect(api.scene, poop.x, poop.y);
      poop.destroy();
      api.updateScore(10);
    }
  }

  /**
   * 불에 타는 파티클 이펙트.
   * - 점화 flash: 호박색 순간 팽창
   * - 불꽃(10개): 3-레이어 색상 (암적 외곽→오렌지→노란 코어), 반투명
   * - 잔불 ember(8개): 글로우+코어 2레이어 다이아몬드, 회전 흩날림
   * - 연기(4개): 어두운 반투명 원, 천천히 위로 퍼짐
   * 모든 Graphics는 tween onComplete에서 자체 destroy.
   */
  private playBurnEffect(scene: Phaser.Scene, cx: number, cy: number): void {
    // 불꽃 물방울 폴리곤 좌표 생성 (로컬 기준)
    const flamePts = (w: number, h: number) => [
      { x:  0,         y: -h       },
      { x:  w * 0.55,  y: -h * 0.1 },
      { x:  w * 0.75,  y:  h * 0.35},
      { x:  w * 0.3,   y:  h       },
      { x: -w * 0.3,   y:  h       },
      { x: -w * 0.75,  y:  h * 0.35},
      { x: -w * 0.55,  y: -h * 0.1 },
    ];

    // ── 0. 점화 flash (호박색) ───────────────────────────────────────
    const flash = scene.add.graphics();
    flash.fillStyle(0xff7700, 0.60);
    flash.fillCircle(0, 0, 17);
    flash.fillStyle(0xffee88, 0.45);
    flash.fillCircle(0, 0, 9);
    flash.setPosition(cx, cy);
    flash.setDepth(202);
    scene.tweens.add({
      targets:  flash,
      scaleX:   2.8,
      scaleY:   2.8,
      alpha:    0,
      duration: 190,
      ease:     'Quad.easeOut',
      onComplete: () => { flash.destroy(); },
    });

    // ── 1. 불꽃 10개 — 3-레이어 색상 + 반투명 ────────────────────────
    for (let i = 0; i < 10; i++) {
      const gfx = scene.add.graphics();
      const w   = Phaser.Math.Between(5, 11);
      const h   = Phaser.Math.Between(14, 27);

      // 외곽: 어두운 적색, 반투명 — 타오르는 가장자리
      gfx.fillStyle(0xaa1100, 0.25);
      gfx.fillPoints(flamePts(w, h), true);

      // 중간: 오렌지
      gfx.fillStyle(0xff4400, 0.48);
      gfx.fillPoints(flamePts(w * 0.70, h * 0.76), true);

      // 코어: 밝은 노란색
      gfx.fillStyle(0xffcc00, 0.68);
      gfx.fillPoints(flamePts(w * 0.40, h * 0.50), true);

      gfx.setPosition(
        cx + Phaser.Math.Between(-15, 15),
        cy + Phaser.Math.Between(-10, 10),
      );
      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-28, 28)));
      gfx.setDepth(200);

      const rise = Phaser.Math.Between(48, 88);
      const dur  = Phaser.Math.Between(500, 900);

      scene.tweens.add({
        targets:  gfx,
        y:        gfx.y - rise * 0.38,
        scaleX:   1.45,
        scaleY:   1.45,
        duration: dur * 0.35,
        ease:     'Quad.easeOut',
        onComplete: () => {
          scene.tweens.add({
            targets:    gfx,
            y:          gfx.y - rise * 0.62,
            scaleX:     0,
            scaleY:     0,
            alpha:      0,
            duration:   dur * 0.65,
            ease:       'Quad.easeIn',
            onComplete: () => { gfx.destroy(); },
          });
        },
      });
    }

    // ── 2. 잔불 ember 8개 — 글로우 + 코어 2레이어 ──────────────────
    const EMBER_COLS = [0xff5500, 0xff8800, 0xffbb00];
    for (let i = 0; i < 8; i++) {
      const gfx   = scene.add.graphics();
      const s     = Phaser.Math.Between(2, 5);
      const color = EMBER_COLS[Math.floor(Math.random() * EMBER_COLS.length)];

      // 외곽 글로우 (반투명)
      gfx.fillStyle(color, 0.18);
      gfx.fillPoints([
        { x:  0,      y: -s * 1.9 },
        { x:  s * 1.9, y:  0      },
        { x:  0,      y:  s * 1.9 },
        { x: -s * 1.9, y:  0      },
      ], true);

      // 코어
      gfx.fillStyle(0xffee88, 0.65);
      gfx.fillPoints([
        { x:  0,  y: -s },
        { x:  s,  y:  0 },
        { x:  0,  y:  s },
        { x: -s,  y:  0 },
      ], true);

      gfx.setPosition(
        cx + Phaser.Math.Between(-18, 18),
        cy + Phaser.Math.Between(-18, 18),
      );
      gfx.setDepth(201);

      const rad = Phaser.Math.DegToRad(Phaser.Math.Between(185, 355));
      const dist = Phaser.Math.Between(28, 65);

      scene.tweens.add({
        targets:  gfx,
        x:        gfx.x + Math.cos(rad) * dist,
        y:        gfx.y + Math.sin(rad) * dist - Phaser.Math.Between(18, 40),
        rotation: Phaser.Math.DegToRad(Phaser.Math.Between(200, 400)),
        alpha:    0,
        scaleX:   0,
        scaleY:   0,
        duration: Phaser.Math.Between(650, 1050),
        delay:    Phaser.Math.Between(0, 220),
        ease:     'Sine.easeOut',
        onComplete: () => { gfx.destroy(); },
      });
    }

    // ── 3. 연기 4개 — 어두운 반투명 원, 천천히 위로 퍼짐 ───────────
    for (let i = 0; i < 4; i++) {
      const gfx = scene.add.graphics();
      const r   = Phaser.Math.Between(6, 13);
      gfx.fillStyle(0x331100, 0.28);
      gfx.fillCircle(0, 0, r);
      gfx.setPosition(
        cx + Phaser.Math.Between(-12, 12),
        cy + Phaser.Math.Between(-10, 4),
      );
      gfx.setDepth(199);

      scene.tweens.add({
        targets:  gfx,
        y:        gfx.y - Phaser.Math.Between(45, 85),
        x:        gfx.x + Phaser.Math.Between(-14, 14),
        scaleX:   2.4,
        scaleY:   2.4,
        alpha:    0,
        duration: Phaser.Math.Between(850, 1350),
        delay:    Phaser.Math.Between(80, 380),
        ease:     'Sine.easeOut',
        onComplete: () => { gfx.destroy(); },
      });
    }
  }
}

