     1→import { BaseAbility } from './BaseAbility';
     2→import type { GameSceneAPI } from './types';
     3→
     4→/**
     5→ * 레거시 (UR)
     6→ * - 기본 효과: 게임 시작 시 6초간 금똥 2개씩 내려오는 피버타임 + 황금 빗줄기(D)
     7→ *             + 똥 스폰마다 20% 확률로 랜덤 2개 화염 추적선(B) + 불태워 소멸 (+10점)
     8→ *             + 캐릭터 주변 상시 불꽃 오라(A)
     9→ * - 특수 능력: 500점마다 레거시 모드 10초 발동
    10→ *             — 점수 1.2배 + 화면 전체 불꽃 폭발 + 황금 실루엣(C) + 테두리 글로우
    11→ *             — 불태우기 강화: 40% 확률로 4개 소멸 / 오라 황금빛으로 강화
    12→ */
    13→export class LegacyAbility extends BaseAbility {
    14→  private startFeverActive = false;
    15→  private legacyModeActive = false;
    16→  private accum           = 0;
    17→  private lastLegacyScore = 0;
    18→  private legacyGlow?:       Phaser.GameObjects.Graphics; // 캐릭터 주변 노란 글로우
    19→  private legacyTopGlow?:    Phaser.GameObjects.Graphics;
    20→  private legacyPulseTween?: Phaser.Tweens.Tween;
    21→
    22→  // A: 상시 불꽃 오라 — delta 누산 타이머
    23→  private oraTimer = 0;
    24→  private static readonly ORA_INTERVAL_NORMAL = 220; // ms
    25→  private static readonly ORA_INTERVAL_LEGACY = 110; // ms (레거시 모드 중 더 빠름)
    26→
    27→  // ── 불꽃 물방울 다각형 좌표 (static 공유) ──────────────────────────
    28→  private static flamePts(w: number, h: number) {
    29→    return [
    30→      { x:  0,         y: -h        },
    31→      { x:  w * 0.55,  y: -h * 0.1  },
    32→      { x:  w * 0.75,  y:  h * 0.35 },
    33→      { x:  w * 0.3,   y:  h        },
    34→      { x: -w * 0.3,   y:  h        },
    35→      { x: -w * 0.75,  y:  h * 0.35 },
    36→      { x: -w * 0.55,  y: -h * 0.1  },
    37→    ];
    38→  }
    39→
    40→  // ─────────────────────────────────────────────────────────────────
    41→  // 생명주기
    42→  // ─────────────────────────────────────────────────────────────────
    43→
    44→  override onCreate(api: GameSceneAPI): void {
    45→    this.startFeverActive = true;
    46→    this.startFeverRain(api);                    // D: 황금 빗줄기 시작
    47→    api.scene.time.delayedCall(6000, () => {
    48→      this.startFeverActive = false;
    49→    });
    50→  }
    51→
    52→  override onUpdate(api: GameSceneAPI): void {
    53→    // A: 불꽃 오라 — 일정 간격마다 파티클 1개 생성
    54→    this.oraTimer += api.scene.game.loop.delta;
    55→    const interval = this.legacyModeActive
    56→      ? LegacyAbility.ORA_INTERVAL_LEGACY
    57→      : LegacyAbility.ORA_INTERVAL_NORMAL;
    58→    if (this.oraTimer >= interval) {
    59→      this.oraTimer -= interval;
    60→      this.spawnOraFlame(api);
    61→    }
    62→
    63→    // 캐릭터 글로우를 플레이어 위치에 맞게 갱신
    64→    if (this.legacyGlow?.active) {
    65→      this.legacyGlow.setPosition(api.player.x, api.player.y);
    66→    }
    67→  }
    68→
    69→  override getTickScore(base: number): number {
    70→    if (!this.legacyModeActive) return base;
    71→    this.accum += base * 0.2;
    72→    const bonus = Math.floor(this.accum);
    73→    this.accum -= bonus;
    74→    return base + bonus;
    75→  }
    76→
    77→  override overrideSpawnPoop(api: GameSceneAPI): boolean {
    78→    if (this.startFeverActive) {
    79→      api.spawnGoldPoop();
    80→      api.spawnGoldPoop();
    81→      return true;
    82→    }
    83→    return false;
    84→  }
    85→
    86→  override onAfterSpawnPoop(api: GameSceneAPI): void {
    87→    const chance = this.legacyModeActive ? 0.4 : 0.2;
    88→    const count  = this.legacyModeActive ? 4   : 2;
    89→    if (Math.random() < chance) {
    90→      this.burnRandomPoops(api, count);
    91→    }
    92→  }
    93→
    94→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
