   154→  private drawFireTrail(
   155→    scene: Phaser.Scene,
   156→    fromX: number, fromY: number,
   157→    toList: { x: number; y: number }[],
   158→  ): void {
   159→    if (toList.length === 0) return;
   160→
   161→    const gfx = scene.add.graphics();
   162→    gfx.setDepth(195);
   163→
   164→    for (const { x, y } of toList) {
   165→      // 외곽: 두꺼운 오렌지 반투명
