   167→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   168→
   169→      // 내부: 얇은 노란 선
   170→      gfx.lineStyle(1.5, 0xffee00, 0.75);
   171→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   172→    }
   173→
   174→    scene.tweens.add({
   175→      targets:  gfx,
   176→      alpha:    0,
   177→      duration: 200,
   178→      ease:     'Quad.easeOut',
   179→      onComplete: () => { gfx.destroy(); },
   180→    });
