   187→  private activateLegacyMode(api: GameSceneAPI): void {
   188→    if (this.legacyModeActive) return;
   189→    this.legacyModeActive = true;
   190→    this.accum = 0;
   191→
   192→    const scene = api.scene;
   193→    const cx    = api.player.x;
   194→    const cy    = api.player.y;
   195→
   196→    // ─ 센티넬 방어막 파괴 스타일 (노란색 버전) ──────────────────────
   197→    // 카메라 노란 flash
   198→    scene.cameras.main.flash(180, 255, 220, 0, true);
   199→
   200→    // 팽창 링 2개
   201→    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
   202→      const ring = scene.add.graphics().setDepth(155);
   203→      ring.lineStyle(2.5, 0xffee44, 0.92);
   204→      ring.strokeEllipse(0, 0, 74, 98);
   205→      ring.setPosition(cx, cy);
   206→      scene.tweens.add({
   207→        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
   208→        duration: 500, delay, ease: 'Quad.easeOut',
   209→        onComplete: () => { ring.destroy(); },
   210→      });
   211→    });
   212→
   213→    // 노란 채움 타원 (빠르게 사라짐)
   214→    const fill = scene.add.graphics().setDepth(154);
   215→    fill.fillStyle(0xffdd00, 0.32);
   216→    fill.fillEllipse(0, 0, 74, 98);
   217→    fill.setPosition(cx, cy);
   218→    scene.tweens.add({
   219→      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
   220→      onComplete: () => { fill.destroy(); },
   221→    });
   222→
   223→    // 파편 8개 (노란 사각형)
   224→    for (let i = 0; i < 8; i++) {
   225→      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
   226→      const speed = Phaser.Math.FloatBetween(45, 100);
   227→      const w     = Phaser.Math.Between(5, 13);
   228→      const h     = Phaser.Math.Between(2, 5);
   229→      const shard = scene.add.graphics().setDepth(156);
   230→      shard.fillStyle(0xffcc00, 1);
   231→      shard.fillRect(-w / 2, -h / 2, w, h);
   232→      shard.setPosition(cx, cy).setRotation(angle);
   233→      scene.tweens.add({
   234→        targets: shard,
   235→        x: cx + Math.cos(angle) * speed,
   236→        y: cy + Math.sin(angle) * speed,
   237→        alpha: 0,
   238→        rotation: angle + Phaser.Math.FloatBetween(-1, 1),
   239→        duration: Phaser.Math.Between(280, 460), ease: 'Quad.easeOut',
   240→        onComplete: () => { shard.destroy(); },
   241→      });
   242→    }
   243→
   244→    // ─ 황금 실루엣 (플레이어 주변 타원) ─────────────────────────
   245→    const silhouette = scene.add.graphics();
   246→    silhouette.fillStyle(0xffdd00, 0.50);
   247→    silhouette.fillEllipse(0, 0, 88, 128);
   248→    silhouette.setPosition(cx, cy).setDepth(157).setAlpha(0);
   249→    scene.tweens.add({
   250→      targets: silhouette, alpha: 1, scaleX: 1.25, scaleY: 1.25,
   251→      duration: 110, ease: 'Quad.easeOut',
   252→      onComplete: () => {
   253→        scene.tweens.add({
   254→          targets: silhouette, alpha: 0, scaleX: 1.8, scaleY: 1.8,
   255→          duration: 300, ease: 'Quad.easeIn',
   256→          onComplete: () => { silhouette.destroy(); },
   257→        });
   258→      },
   259→    });
   260→
   261→    // ─ 화면 전체 불꽃 폭발 (20개) ────────────────────────────────
   262→    const BURST_COLS = [0xff2200, 0xff6600, 0xffaa00, 0xffdd00, 0xffff88];
   263→    for (let i = 0; i < 20; i++) {
   264→      const gfx = scene.add.graphics();
   265→      const w   = Phaser.Math.Between(4, 10);
   266→      const h   = Phaser.Math.Between(10, 22);
   267→      const col = BURST_COLS[Math.floor(Math.random() * BURST_COLS.length)];
