   270→      gfx.fillPoints(LegacyAbility.flamePts(w, h), true);
   271→      gfx.fillStyle(0xffee88, Phaser.Math.FloatBetween(0.28, 0.55));
   272→      gfx.fillPoints(LegacyAbility.flamePts(w * 0.4, h * 0.5), true);
   273→
   274→      gfx.setPosition(Phaser.Math.Between(20, 380), Phaser.Math.Between(40, 560));
   275→      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-180, 180)));
   276→      gfx.setDepth(158).setAlpha(0);
   277→
   278→      const delay = Phaser.Math.Between(0, 280);
   279→      scene.tweens.add({
   280→        targets: gfx, alpha: 1,
   281→        scaleX: Phaser.Math.FloatBetween(1.2, 1.9),
   282→        scaleY: Phaser.Math.FloatBetween(1.2, 1.9),
   283→        duration: 140, delay, ease: 'Quad.easeOut',
