   288→            onComplete: () => { gfx.destroy(); },
   289→          });
   290→        },
   291→      });
   292→    }
   293→
   294→    // ─ 상단 노란빛 그라데이션 (위에서 아래로 퍼지는 빛) ─────────
   295→    this.legacyTopGlow = scene.add.graphics();
   296→    // fillGradientStyle: 상단 alpha 0.28 → 하단 alpha 0 (노란 빛이 위에서 내려오는 느낌)
   297→    this.legacyTopGlow.fillGradientStyle(0xffee00, 0xffee00, 0xffee00, 0xffee00, 0.28, 0.28, 0, 0);
   298→    this.legacyTopGlow.fillRect(0, 0, 400, 220);
   299→    this.legacyTopGlow.setDepth(148);
   300→
   301→    // ─ 캐릭터 노란 글로우 (동심 타원 4겹, 플레이어 추적) ──────────
   302→    // 한 번 그리고 setPosition만 갱신 → 매 프레임 redraw 없음
   303→    this.legacyGlow = scene.add.graphics();
   304→    // 바깥부터 안쪽으로 점점 진해지는 노란 글로우
   305→    this.legacyGlow.fillStyle(0xffee00, 0.08); this.legacyGlow.fillEllipse(0, 0, 110, 140);
   306→    this.legacyGlow.fillStyle(0xffee00, 0.14); this.legacyGlow.fillEllipse(0, 0,  88, 114);
   307→    this.legacyGlow.fillStyle(0xffee00, 0.22); this.legacyGlow.fillEllipse(0, 0,  70,  92);
   308→    this.legacyGlow.fillStyle(0xffdd00, 0.32); this.legacyGlow.fillEllipse(0, 0,  56,  74);
   309→    this.legacyGlow.setPosition(cx, cy).setDepth(87); // 플레이어 바로 뒤
   310→
   311→    // 글로우 + 상단 빛 동시 펄스
   312→    this.legacyPulseTween = scene.tweens.add({
   313→      targets:  [this.legacyGlow, this.legacyTopGlow],
   314→      alpha:    0.55,
   315→      duration: 600, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
   316→    });
   317→
   318→    // 10초 후 종료
   319→    scene.time.delayedCall(10000, () => {
   320→      this.legacyModeActive = false;
   321→      this.legacyPulseTween?.stop();
   322→      this.legacyPulseTween = undefined;
   323→      scene.tweens.add({
   324→        targets: [this.legacyGlow, this.legacyTopGlow],
   325→        alpha: 0, duration: 400, ease: 'Quad.easeOut',
   326→        onComplete: () => {
   327→          this.legacyGlow?.destroy();
   328→          this.legacyGlow = undefined;
   329→          this.legacyTopGlow?.destroy();
   330→          this.legacyTopGlow = undefined;
   331→        },
   332→      });
   333→    });
   334→  }
