      { x:  0,         y: -h        },
      { x:  w * 0.55,  y: -h * 0.1  },
      { x:  w * 0.75,  y:  h * 0.35 },
      { x:  w * 0.3,   y:  h        },
      { x: -w * 0.3,   y:  h        },
      { x: -w * 0.75,  y:  h * 0.35 },
      { x: -w * 0.55,  y: -h * 0.1  },
    ];
  }

  // ─────────────────────────────────────────────────────────────────
  // 생명주기
  // ─────────────────────────────────────────────────────────────────

  override onCreate(api: GameSceneAPI): void {
    this.startFeverActive = true;
